*{padding:0;margin:0;}
.dg-render-scope[data-system="EXW"], .dg-render-scope[data-system="EXW"]{width:100%;background:#fff;-webkit-overflow-scrolling:touch;-webkit-text-size-adjust:100%;}
.dg-render-scope[data-system="EXW"], .dg-render-scope[data-system="EXW"], .dg-render-scope[data-system="EXW"] h1, .dg-render-scope[data-system="EXW"] h2, .dg-render-scope[data-system="EXW"] h3, .dg-render-scope[data-system="EXW"] h4, .dg-render-scope[data-system="EXW"] h5, .dg-render-scope[data-system="EXW"] h6, .dg-render-scope[data-system="EXW"] div, .dg-render-scope[data-system="EXW"] fieldset, .dg-render-scope[data-system="EXW"] p, .dg-render-scope[data-system="EXW"] span{padding:0;margin:0;border:0;font-size:13px;font-weight:300;color:#4a4d5d;font-family:'NanumSquareR', 'Sans-serif';line-height:1.2;-webkit-tap-highlight-color:transparent;}
.dg-render-scope[data-system="EXW"] *:focus{outline:none;}
.dg-render-scope[data-system="EXW"] button{border:0;border-radius:0;box-shadow:none;background:none;font-family:'NanumSquareR', 'Sans-serif';appearance:none;cursor:pointer;}
.dg-render-scope[data-system="EXW"] button:focus{outline:none;}
.dg-render-scope[data-system="EXW"] table{table-layout:fixed;width:100%;}
.dg-render-scope[data-system="EXW"] img{vertical-align:top;}
.dg-render-scope[data-system="EXW"] input, .dg-render-scope[data-system="EXW"] select{vertical-align:middle;border-radius:0;font-family:'NanumSquareR', 'Sans-serif';}
.dg-render-scope[data-system="EXW"] strong{font-weight:normal;}
.dg-render-scope[data-system="EXW"] ul, .dg-render-scope[data-system="EXW"] ol{list-style:none;}
.dg-render-scope[data-system="EXW"] em{font-style:normal;}
.dg-render-scope[data-system="EXW"] a{color:inherit;text-decoration:none;}
.dg-render-scope[data-system="EXW"] a:visited, .dg-render-scope[data-system="EXW"] a:hover{text-decoration:none;}
.dg-render-scope[data-system="EXW"] caption span, .dg-render-scope[data-system="EXW"] legend{overflow:hidden;position:absolute;left:-9999px;}
.dg-render-scope[data-system="EXW"] .t_left{text-align:left !important;}
